-- Policy B staging kit, step S05. Generated by scripts/db-verify/staging/build-policy-b-kit.sh
-- from the proposed migration, verbatim. Do not edit; rebuild. Staging only: never run against the production project.

-- Refuse to run anywhere but an empty or synthetic-only staging database.
DO $guard$
DECLARE
  v_bad boolean;
BEGIN
  IF to_regclass('public.vehicle_listings') IS NOT NULL THEN
    EXECUTE $q$SELECT EXISTS (SELECT 1 FROM public.vehicle_listings WHERE vin NOT LIKE 'EXAMPLEVIN%')$q$ INTO v_bad;
    IF v_bad THEN RAISE EXCEPTION 'staging guard: non-synthetic vehicles present; this is not the policy B staging database'; END IF;
  END IF;
  IF to_regclass('public.tenants') IS NOT NULL THEN
    EXECUTE $q$SELECT EXISTS (SELECT 1 FROM public.tenants WHERE slug NOT LIKE '%example-motors')$q$ INTO v_bad;
    IF v_bad THEN RAISE EXCEPTION 'staging guard: non-synthetic dealerships present; this is not the policy B staging database'; END IF;
  END IF;
END
$guard$;

-- ===== supabase/proposed/20261031000000_doc_fee_basis_policy_b.sql =====
-- Doc fee change, policy B (owner-approved design, 2026-10-28). PROPOSED.
-- Not applied to any hosted project. Verified only in isolated databases
-- (scripts/db-verify/run.sh --policy-b). Apply only with the owner's separate
-- authorization, through the staged plan in ADMIN_V2_RELEASE_READINESS.md 10.10.
--
-- Policy:
--   includes_fee  `price` is the dealer's authoritative advertised total. A fee
--                 change keeps it and rederives advertised_price_before_doc =
--                 price - fee. website_sale_price is kept as stored.
--   before_fee    advertised_price_before_doc is the authoritative vehicle
--                 price. A fee change keeps it and derives website_sale_price =
--                 before-fee + fee.
--   A fee change never writes price_last_verified_at, price_parse_status or
--   price_parse_notes, never touches archived vehicles unless they are
--   explicitly included, and never rewrites a value to make arithmetic agree.
--
-- Fee basis authority (doc_fee_basis): only the dealership's explicit
-- setting decides. advertised_includes_doc_fee (or the legacy
-- advertised_excludes_doc_fee, read as its inverse) must be a readable
-- boolean. Missing, unreadable or contradictory settings leave the basis
-- 'unconfigured' or 'conflict', and no fee change can be applied. The display
-- mode is never used to guess it.
--
-- Dealership-level block (doc_fee_change_review): a fee change is refused,
-- with nothing written, while any of these hold for the vehicles in scope:
--   the basis is unconfigured or contradictory;
--   a stored before-fee price does not add up to the total (split_mismatch);
--   the new fee would leave a vehicle with no vehicle price (invalid);
--   on includes_fee, website_sale_price differs from the total;
--   the latest website observation contradicts the configured basis.
-- There is no exception path. Any future exception needs separate owner
-- approval and its own migration.
--
-- Fee settings change only through admin_doc_fee_change_apply once a
-- dealership has priced vehicles: merge_dealer_settings refuses a changed
-- doc_fee_enabled or doc_fee_amount there, so a tenant-wide fee can never be
-- saved without its vehicles. recalc_tenant_doc_fee, which restamped
-- verification dates, cleared parser warnings and reached archived stock,
-- is retired.

CREATE OR REPLACE FUNCTION public.doc_fee_setting_bool(p_value jsonb)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN jsonb_typeof(p_value) = 'boolean' THEN p_value::text::boolean
    WHEN jsonb_typeof(p_value) = 'string' AND lower(btrim(p_value #>> '{}')) = 'true' THEN true
    WHEN jsonb_typeof(p_value) = 'string' AND lower(btrim(p_value #>> '{}')) = 'false' THEN false
    ELSE NULL
  END
$function$;

CREATE OR REPLACE FUNCTION public.doc_fee_basis(p_settings jsonb, OUT basis text, OUT basis_source text)
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public'
AS $function$
DECLARE
  v_s jsonb := CASE WHEN jsonb_typeof(p_settings) = 'object' THEN p_settings ELSE '{}'::jsonb END;
  v_has_inc boolean := v_s ? 'advertised_includes_doc_fee' AND jsonb_typeof(v_s -> 'advertised_includes_doc_fee') <> 'null';
  v_has_exc boolean := v_s ? 'advertised_excludes_doc_fee' AND jsonb_typeof(v_s -> 'advertised_excludes_doc_fee') <> 'null';
  v_inc boolean := public.doc_fee_setting_bool(v_s -> 'advertised_includes_doc_fee');
  v_exc boolean := public.doc_fee_setting_bool(v_s -> 'advertised_excludes_doc_fee');
BEGIN
  IF (v_has_inc AND v_inc IS NULL) OR (v_has_exc AND v_exc IS NULL) THEN
    basis := 'unconfigured'; basis_source := 'unreadable_setting';
  ELSIF v_inc IS NOT NULL AND v_exc IS NOT NULL AND v_inc = v_exc THEN
    basis := 'conflict'; basis_source := 'settings_conflict';
  ELSIF v_inc IS NOT NULL THEN
    basis := CASE WHEN v_inc THEN 'includes_fee' ELSE 'before_fee' END; basis_source := 'advertised_includes_doc_fee';
  ELSIF v_exc IS NOT NULL THEN
    basis := CASE WHEN v_exc THEN 'before_fee' ELSE 'includes_fee' END; basis_source := 'advertised_excludes_doc_fee';
  ELSE
    basis := 'unconfigured'; basis_source := 'not_set';
  END IF;
END;
$function$;

COMMENT ON FUNCTION public.doc_fee_basis(jsonb) IS
  'The fee basis from the dealership''s explicit setting only: includes_fee, before_fee, conflict or unconfigured, and where it was read. Mirrors resolveFeeBasis in src/lib/admin/pricing/feeBasis.ts.';

-- One vehicle under a fee change. status:
--   change          derived fields or the fee move
--   unchanged       nothing to write
--   no_price        nothing to anchor on; left alone, reported
--   split_mismatch  the stored before-fee price does not add up to the total
--   invalid         the fee would leave no vehicle price
--   blocked_basis   the dealership basis is unconfigured or contradictory
-- sale_price_differs: on includes_fee, website_sale_price is not the total.
CREATE OR REPLACE FUNCTION public.doc_fee_row_plan(
  p_basis text,
  p_price numeric,
  p_advertised_before_doc numeric,
  p_website_sale_price numeric,
  p_doc_fee numeric,
  p_fee numeric,
  OUT status text,
  OUT selling_before numeric,
  OUT selling_after numeric,
  OUT total_before numeric,
  OUT total_after numeric,
  OUT advertised_before_doc_after numeric,
  OUT website_sale_price_after numeric,
  OUT sale_price_differs boolean
)
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public'
AS $function$
DECLARE
  v_fee numeric := round(coalesce(p_fee, 0), 2);
BEGIN
  sale_price_differs := false;
  advertised_before_doc_after := p_advertised_before_doc;
  website_sale_price_after := p_website_sale_price;
  IF p_basis NOT IN ('includes_fee', 'before_fee') THEN
    status := 'blocked_basis';
    RETURN;
  END IF;
  IF p_basis = 'includes_fee' THEN
    IF p_price IS NULL OR p_price <= 0 THEN
      status := 'no_price';
      RETURN;
    END IF;
    total_before := p_price;
    total_after := p_price;
    sale_price_differs := p_website_sale_price IS NOT NULL AND abs(p_website_sale_price - p_price) >= 0.01;
    IF p_advertised_before_doc IS NOT NULL AND abs(p_advertised_before_doc + coalesce(p_doc_fee, 0) - p_price) >= 0.01 THEN
      status := 'split_mismatch';
      selling_before := p_advertised_before_doc;
      selling_after := p_advertised_before_doc;
      RETURN;
    END IF;
    selling_before := round(p_price - coalesce(p_doc_fee, 0), 2);
    selling_after := round(p_price - v_fee, 2);
    IF selling_after <= 0 THEN
      status := 'invalid';
      RETURN;
    END IF;
    advertised_before_doc_after := selling_after;
    status := CASE WHEN p_doc_fee IS DISTINCT FROM v_fee OR p_advertised_before_doc IS DISTINCT FROM selling_after THEN 'change' ELSE 'unchanged' END;
    RETURN;
  END IF;
  IF p_advertised_before_doc IS NULL THEN
    status := 'no_price';
    RETURN;
  END IF;
  selling_before := p_advertised_before_doc;
  selling_after := p_advertised_before_doc;
  total_before := p_website_sale_price;
  total_after := round(p_advertised_before_doc + v_fee, 2);
  IF p_price IS NOT NULL AND abs(p_price - p_advertised_before_doc) >= 0.01 THEN
    status := 'split_mismatch';
    total_after := p_website_sale_price;
    RETURN;
  END IF;
  IF p_advertised_before_doc <= 0 THEN
    status := 'invalid';
    RETURN;
  END IF;
  website_sale_price_after := total_after;
  status := CASE WHEN p_doc_fee IS DISTINCT FROM v_fee OR p_website_sale_price IS DISTINCT FROM total_after THEN 'change' ELSE 'unchanged' END;
END;
$function$;

COMMENT ON FUNCTION public.doc_fee_row_plan(text, numeric, numeric, numeric, numeric, numeric) IS
  'One vehicle under a fee change. Mirrors planFeeChange in src/lib/admin/pricing/feeBasis.ts.';

-- Does the latest website observation contradict the basis? includes_fee
-- expects the website to show the total; a page showing the total plus or
-- minus the fee says otherwise. before_fee expects the vehicle price or the
-- vehicle price plus the fee; a page showing the inventory price minus the
-- fee says the inventory price already holds it.
CREATE OR REPLACE FUNCTION public.doc_fee_evidence_contradicts(p_basis text, p_price numeric, p_doc_fee numeric, p_observed numeric)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_observed IS NULL OR p_price IS NULL OR coalesce(p_doc_fee, 0) <= 0 THEN false
    WHEN p_basis = 'includes_fee' THEN abs(p_observed - p_price) >= 1
         AND (abs(p_observed - (p_price + p_doc_fee)) < 1 OR abs(p_observed - (p_price - p_doc_fee)) < 1)
    WHEN p_basis = 'before_fee' THEN abs(p_observed - (p_price - p_doc_fee)) < 1
    ELSE false
  END
$function$;

-- The dealership-level review shared by the dry-run, the apply and the
-- block: the basis, the counts in scope, and why a change is refused.
CREATE OR REPLACE FUNCTION public.doc_fee_change_review(p_tenant_id uuid, p_fee numeric, p_include_archived boolean)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_settings jsonb;
  v_basis text;
  v_basis_source text;
  v_counts record;
  v_evidence integer;
  v_reasons text[] := ARRAY[]::text[];
BEGIN
  SELECT settings INTO v_settings FROM public.dealer_profiles WHERE tenant_id = p_tenant_id;
  SELECT b.basis, b.basis_source INTO v_basis, v_basis_source FROM public.doc_fee_basis(v_settings) b;

  SELECT
    count(*) FILTER (WHERE in_scope AND p.status = 'change') AS change,
    count(*) FILTER (WHERE in_scope AND p.status = 'unchanged') AS unchanged,
    count(*) FILTER (WHERE l.archived_at IS NOT NULL AND NOT p_include_archived AND p.status = 'change') AS archived_excluded,
    count(*) FILTER (WHERE in_scope AND p.status = 'no_price') AS no_price,
    count(*) FILTER (WHERE in_scope AND p.status = 'split_mismatch') AS split_mismatch,
    count(*) FILTER (WHERE in_scope AND p.status = 'invalid') AS invalid,
    count(*) FILTER (WHERE in_scope AND p.sale_price_differs) AS sale_price_differs,
    count(*) FILTER (WHERE in_scope AND p.status = 'change' AND l.price_parse_status = 'warning') AS parse_warnings,
    count(*) FILTER (WHERE NOT in_scope) AS out_of_scope
  INTO v_counts
  FROM public.vehicle_listings l
  CROSS JOIN LATERAL (SELECT (l.archived_at IS NULL OR p_include_archived) AS in_scope) s
  CROSS JOIN LATERAL public.doc_fee_row_plan(v_basis, l.price, l.advertised_price_before_doc, l.website_sale_price, l.doc_fee, p_fee) p
  WHERE l.tenant_id = p_tenant_id;

  SELECT count(*) INTO v_evidence
  FROM public.vehicle_listings l
  CROSS JOIN LATERAL (
    SELECT ap.advertised_price
    FROM public.advertised_prices ap
    WHERE ap.tenant_id = l.tenant_id AND upper(ap.vin) = upper(l.vin)
      AND coalesce(ap.source_channel, 'website') = 'website'
    ORDER BY ap.captured_at DESC
    LIMIT 1
  ) w
  WHERE l.tenant_id = p_tenant_id
    AND (l.archived_at IS NULL OR p_include_archived)
    AND public.doc_fee_evidence_contradicts(v_basis, l.price, l.doc_fee, w.advertised_price);

  IF v_basis = 'unconfigured' THEN
    v_reasons := v_reasons || 'The dealership has not set whether its advertised prices include the document fee.'::text;
  ELSIF v_basis = 'conflict' THEN
    v_reasons := v_reasons || 'The dealership''s fee basis settings contradict each other.'::text;
  END IF;
  IF v_counts.split_mismatch > 0 THEN
    v_reasons := v_reasons || format('%s vehicle(s) have a stored vehicle price that does not add up to the advertised total.', v_counts.split_mismatch);
  END IF;
  IF v_counts.invalid > 0 THEN
    v_reasons := v_reasons || format('%s vehicle(s) would be left with no vehicle price under this fee.', v_counts.invalid);
  END IF;
  IF v_basis = 'includes_fee' AND v_counts.sale_price_differs > 0 THEN
    v_reasons := v_reasons || format('%s vehicle(s) store a sale price (website_sale_price) that differs from the advertised total.', v_counts.sale_price_differs);
  END IF;
  IF v_evidence > 0 THEN
    v_reasons := v_reasons || format('%s vehicle(s) have a website observation that contradicts the configured fee basis.', v_evidence);
  END IF;

  RETURN jsonb_build_object(
    'basis', v_basis,
    'basis_source', v_basis_source,
    'eligible', CASE WHEN v_basis IN ('includes_fee', 'before_fee') THEN v_counts.change ELSE 0 END,
    'unchanged', v_counts.unchanged,
    'excluded_archived', v_counts.archived_excluded,
    'no_price_basis', v_counts.no_price,
    'split_mismatches', v_counts.split_mismatch,
    'invalid', v_counts.invalid,
    'source_mismatches', CASE WHEN v_basis = 'includes_fee' THEN v_counts.sale_price_differs ELSE 0 END,
    'evidence_conflicts', v_evidence,
    'parse_warnings', v_counts.parse_warnings,
    'blocked', cardinality(v_reasons) > 0,
    'block_reasons', to_jsonb(v_reasons));
END;
$function$;

REVOKE ALL ON FUNCTION public.doc_fee_change_review(uuid, numeric, boolean) FROM PUBLIC, anon, authenticated;

COMMENT ON FUNCTION public.doc_fee_change_review(uuid, numeric, boolean) IS
  'Dealership-level fee change review: basis, counts in scope and the reasons a change is blocked. Internal to the preview and apply routines.';

CREATE OR REPLACE FUNCTION public.admin_doc_fee_change_preview(
  p_tenant_id uuid,
  p_enabled boolean,
  p_amount numeric,
  p_include_archived boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_fee numeric;
  v_version bigint;
  v_review jsonb;
  v_basis text;
  v_samples jsonb;
  v_warnings text[] := ARRAY[]::text[];
BEGIN
  IF NOT (
    public.has_role((SELECT auth.uid()), 'admin'::public.app_role)
    OR public.tenant_role_in(p_tenant_id, ARRAY['owner','admin','general_manager','gsm'])
  ) THEN
    RAISE EXCEPTION 'not authorized for tenant %', p_tenant_id USING ERRCODE = '42501';
  END IF;
  IF p_amount IS NULL OR p_amount < 0 THEN
    RAISE EXCEPTION 'fee amount must be zero or more';
  END IF;

  v_fee := CASE WHEN p_enabled THEN round(p_amount, 2) ELSE 0 END;
  v_version := coalesce((SELECT policy_version FROM public.dealer_profiles WHERE tenant_id = p_tenant_id), 1);
  v_review := public.doc_fee_change_review(p_tenant_id, v_fee, p_include_archived);
  v_basis := v_review ->> 'basis';

  SELECT coalesce(jsonb_agg(s), '[]'::jsonb) INTO v_samples
  FROM (
    SELECT jsonb_build_object(
      'vin_suffix', right(l.vin, 6),
      'basis', v_basis,
      'selling_price', p.selling_after,
      'selling_before', p.selling_before,
      'selling_after', p.selling_after,
      'fee_before', l.doc_fee,
      'fee_after', v_fee,
      'total_before', p.total_before,
      'total_after', p.total_after,
      'source_mismatch', p.sale_price_differs,
      'archived', l.archived_at IS NOT NULL
    ) AS s
    FROM public.vehicle_listings l
    CROSS JOIN LATERAL public.doc_fee_row_plan(v_basis, l.price, l.advertised_price_before_doc, l.website_sale_price, l.doc_fee, v_fee) p
    WHERE l.tenant_id = p_tenant_id
      AND (l.archived_at IS NULL OR p_include_archived)
      AND p.status = 'change'
    ORDER BY l.archived_at NULLS FIRST, l.price_last_verified_at DESC NULLS LAST, l.vin
    LIMIT 5
  ) q;

  IF v_basis = 'includes_fee' THEN
    v_warnings := v_warnings || 'Advertised prices include the fee: each advertised total is kept and the fee is taken out of the vehicle price.'::text;
  ELSIF v_basis = 'before_fee' THEN
    v_warnings := v_warnings || 'Advertised prices exclude the fee: each vehicle price is kept and the fee is added on top.'::text;
  END IF;
  IF (v_review ->> 'no_price_basis')::int > 0 THEN
    v_warnings := v_warnings || format('%s active vehicle(s) have no advertised price basis and are not affected.', v_review ->> 'no_price_basis');
  END IF;
  IF (v_review ->> 'parse_warnings')::int > 0 THEN
    v_warnings := v_warnings || format('%s active vehicle(s) carry a price parse warning; it is preserved.', v_review ->> 'parse_warnings');
  END IF;
  IF p_include_archived THEN
    v_warnings := v_warnings || 'Archived vehicles are included by explicit request.'::text;
  END IF;
  v_warnings := v_warnings || 'Source verification dates and mismatch flags are preserved; recalculation is not a fresh observation.'::text;

  RETURN v_review || jsonb_build_object(
    'version', v_version,
    'computed_at', now(),
    'fee', v_fee,
    'samples', v_samples,
    'warnings', to_jsonb(v_warnings));
END;
$function$;

CREATE OR REPLACE FUNCTION public.admin_doc_fee_change_apply(
  p_tenant_id uuid,
  p_enabled boolean,
  p_amount numeric,
  p_expected_version bigint,
  p_idempotency_key text,
  p_include_archived boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := (SELECT auth.uid());
  v_fee numeric;
  v_current bigint;
  v_prev jsonb;
  v_review jsonb;
  v_basis text;
  v_changes jsonb;
  v_count integer;
  v_audit_id uuid;
  v_result jsonb;
  v_existing jsonb;
  v_requested jsonb;
BEGIN
  IF NOT (
    public.has_role(v_uid, 'admin'::public.app_role)
    OR public.tenant_role_in(p_tenant_id, ARRAY['owner','admin','general_manager','gsm'])
  ) THEN
    RAISE EXCEPTION 'not authorized for tenant %', p_tenant_id USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'idempotency key required';
  END IF;
  IF p_amount IS NULL OR p_amount < 0 THEN
    RAISE EXCEPTION 'fee amount must be zero or more';
  END IF;
  IF p_expected_version IS NULL THEN
    RAISE EXCEPTION 'expected policy version required';
  END IF;

  SELECT result INTO v_existing
  FROM public.admin_policy_applications
  WHERE idempotency_key = p_idempotency_key;
  IF v_existing IS NOT NULL THEN
    RETURN v_existing || jsonb_build_object('status', 'duplicate', 'original_status', v_existing->>'status');
  END IF;

  v_fee := CASE WHEN p_enabled THEN round(p_amount, 2) ELSE 0 END;
  v_requested := jsonb_build_object(
    'enabled', p_enabled, 'amount', p_amount, 'include_archived', p_include_archived,
    'expected_version', p_expected_version);

  INSERT INTO public.dealer_profiles (tenant_id, settings, updated_by)
  VALUES (p_tenant_id, '{}'::jsonb, v_uid)
  ON CONFLICT (tenant_id) DO NOTHING;

  SELECT policy_version, coalesce(settings, '{}'::jsonb)
    INTO v_current, v_prev
  FROM public.dealer_profiles
  WHERE tenant_id = p_tenant_id
  FOR UPDATE;

  SELECT result INTO v_existing
  FROM public.admin_policy_applications
  WHERE idempotency_key = p_idempotency_key;
  IF v_existing IS NOT NULL THEN
    RETURN v_existing || jsonb_build_object('status', 'duplicate', 'original_status', v_existing->>'status');
  END IF;

  IF v_current IS DISTINCT FROM p_expected_version THEN
    RETURN jsonb_build_object('status', 'conflict', 'affected', 0, 'version', v_current, 'audit_id', NULL);
  END IF;

  -- The vehicles are held for the length of the change, so a feed or crawl
  -- write cannot slip between the review and the update.
  PERFORM 1 FROM public.vehicle_listings WHERE tenant_id = p_tenant_id FOR UPDATE;

  v_review := public.doc_fee_change_review(p_tenant_id, v_fee, p_include_archived);
  v_basis := v_review ->> 'basis';

  -- The dealership-level block: the fee setting and every vehicle move
  -- together or not at all. The refusal itself is recorded.
  IF (v_review ->> 'blocked')::boolean THEN
    INSERT INTO public.audit_log (action, entity_type, entity_id, store_id, user_id, details)
    VALUES ('doc_fee_policy_blocked', 'tenant', p_tenant_id::text, p_tenant_id::text, v_uid,
      jsonb_build_object('requested', v_requested, 'fee', v_fee, 'review', v_review, 'idempotency_key', p_idempotency_key))
    RETURNING id INTO v_audit_id;
    RETURN jsonb_build_object('status', 'blocked', 'affected', 0, 'version', v_current, 'audit_id', v_audit_id,
      'basis', v_basis, 'block_reasons', v_review -> 'block_reasons',
      'message', 'Nothing was changed. ' || array_to_string(ARRAY(SELECT jsonb_array_elements_text(v_review -> 'block_reasons')), ' '));
  END IF;

  -- Before and after for every vehicle this change writes, kept with the audit row.
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'listing_id', l.id, 'vin_suffix', right(l.vin, 6),
           'before', jsonb_build_object('price', l.price, 'advertised_price_before_doc', l.advertised_price_before_doc, 'doc_fee', l.doc_fee, 'website_sale_price', l.website_sale_price),
           'after', jsonb_build_object('price', l.price, 'advertised_price_before_doc', p.advertised_before_doc_after, 'doc_fee', v_fee, 'website_sale_price', p.website_sale_price_after))
         ORDER BY l.vin), '[]'::jsonb)
    INTO v_changes
  FROM public.vehicle_listings l
  CROSS JOIN LATERAL public.doc_fee_row_plan(v_basis, l.price, l.advertised_price_before_doc, l.website_sale_price, l.doc_fee, v_fee) p
  WHERE l.tenant_id = p_tenant_id
    AND (l.archived_at IS NULL OR p_include_archived)
    AND p.status = 'change';

  UPDATE public.dealer_profiles
  SET settings = coalesce(settings, '{}'::jsonb)
                 || jsonb_build_object('doc_fee_enabled', p_enabled, 'doc_fee_amount', p_amount),
      updated_by = v_uid
  WHERE tenant_id = p_tenant_id
  RETURNING policy_version INTO v_current;

  -- Derived fields and the fee only. Verification stamps, parse status and
  -- notes are untouched: recalculation is not an observation.
  UPDATE public.vehicle_listings l
  SET doc_fee = v_fee,
      advertised_price_before_doc = p.advertised_before_doc_after,
      website_sale_price = p.website_sale_price_after,
      price_recalculated_at = now()
  FROM public.vehicle_listings src
  CROSS JOIN LATERAL public.doc_fee_row_plan(v_basis, src.price, src.advertised_price_before_doc, src.website_sale_price, src.doc_fee, v_fee) p
  WHERE src.id = l.id
    AND l.tenant_id = p_tenant_id
    AND (l.archived_at IS NULL OR p_include_archived)
    AND p.status = 'change';
  GET DIAGNOSTICS v_count = ROW_COUNT;

  INSERT INTO public.audit_log (action, entity_type, entity_id, store_id, user_id, details)
  VALUES (
    'doc_fee_policy_applied', 'tenant', p_tenant_id::text, p_tenant_id::text, v_uid,
    jsonb_build_object(
      'prev', jsonb_build_object('doc_fee_enabled', v_prev->'doc_fee_enabled', 'doc_fee_amount', v_prev->'doc_fee_amount'),
      'next', jsonb_build_object('doc_fee_enabled', p_enabled, 'doc_fee_amount', p_amount),
      'fee_applied', v_fee,
      'basis', v_basis,
      'basis_source', v_review ->> 'basis_source',
      'affected', v_count,
      'changes', v_changes,
      'include_archived', p_include_archived,
      'expected_version', p_expected_version,
      'version', v_current,
      'idempotency_key', p_idempotency_key))
  RETURNING id INTO v_audit_id;

  v_result := jsonb_build_object('status', 'applied', 'affected', v_count, 'version', v_current, 'audit_id', v_audit_id, 'basis', v_basis);

  INSERT INTO public.admin_policy_applications (idempotency_key, tenant_id, policy, requested, result, applied_by)
  VALUES (p_idempotency_key, p_tenant_id, 'doc_fee', v_requested, v_result, v_uid);

  RETURN v_result;
EXCEPTION
  WHEN unique_violation THEN
    SELECT result INTO v_existing
    FROM public.admin_policy_applications
    WHERE idempotency_key = p_idempotency_key;
    RETURN coalesce(v_existing, jsonb_build_object('status', 'failed', 'affected', 0, 'version', NULL, 'audit_id', NULL))
           || jsonb_build_object('status', 'duplicate');
END;
$function$;

-- Retired. It saved nothing itself, read a fee saved earlier by a separate
-- call, restamped price_last_verified_at, reset parser warnings and reached
-- archived vehicles. admin_doc_fee_change_apply replaces it.
CREATE OR REPLACE FUNCTION public.recalc_tenant_doc_fee(p_tenant_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'recalc_tenant_doc_fee is retired; use admin_doc_fee_change_apply' USING ERRCODE = '0A000';
END;
$function$;

REVOKE ALL ON FUNCTION public.recalc_tenant_doc_fee(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.recalc_tenant_doc_fee(uuid) TO authenticated, service_role;

-- merge_dealer_settings, as applied in 20261029001000, with two changes:
--   the fee basis keys join the pricing class (they were dealership settings
--   any settings manager could change);
--   a changed doc_fee_enabled or doc_fee_amount is refused once the
--   dealership has priced vehicles, so the fee only moves together with
--   them through admin_doc_fee_change_apply.
CREATE OR REPLACE FUNCTION public.merge_dealer_settings(_tenant_id uuid, _patch jsonb)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := (SELECT auth.uid());
  v_role text;
  v_admin boolean;
  v_keys text[];
  v_touched text[];
  v_class record;
  v_current jsonb;
  v_service_keys text[] := ARRAY[
    'k208_authority_roles','k208_authorized_users',
    'require_safety_inspection','require_k208_licensee_certification',
    'service_failure_photo_required','service_reinspection_managers_only',
    'service_pass_all_enabled','service_overdue_hours'];
  v_service_roles text[] := ARRAY['owner','general_manager','gsm','admin','manager','service_manager'];
  v_pricing_keys text[] := ARRAY[
    'doc_fee_enabled','doc_fee_amount','doc_fee_state',
    'advertised_includes_doc_fee','advertised_excludes_doc_fee',
    'price_display_mode','price_label','comp_settings',
    'todays_price_mode','todays_price_custom','financing_disclosure_apr',
    'title_policy_no_branded'];
  v_pricing_roles text[] := ARRAY['owner','admin','general_manager','gsm'];
  v_routing_keys text[] := ARRAY[
    'passport_contact_routing','passport_agents','vehicle_agent_assignments','passport_rotation_state'];
  v_routing_roles text[] := ARRAY['owner','admin','general_manager','gsm','manager','sales_manager','used_car_manager','finance'];
  v_publishing_keys text[] := ARRAY[
    'ingest_auto_publish','document_rules','require_install_verification',
    'ingest_recon_dispatch','ingest_detail_dispatch','factory_sticker',
    'packet_module_defaults','passport_version','history_report_links_enabled'];
  v_addon_keys text[] := ARRAY[
    'dealer_programs','oem_factory_warranties','cpo_programs',
    'product_default_mode','allow_type_override_at_signing'];
  v_addon_roles text[] := ARRAY['owner','admin','general_manager','gsm','manager','sales_manager','used_car_manager','finance','office','compliance'];
  v_member_keys text[] := ARRAY['label_defaults','used_sticker_options','inventory_show_quick_actions'];
  v_settings_roles text[] := ARRAY['owner','admin','general_manager','gsm','manager'];
BEGIN
  SELECT lower(trim(tm.role)) INTO v_role
    FROM public.tenant_members tm
    WHERE tm.tenant_id = _tenant_id AND tm.user_id = v_uid AND tm.accepted_at IS NOT NULL
    LIMIT 1;
  v_admin := public.has_role(v_uid, 'admin'::public.app_role);
  IF v_role IS NULL AND NOT v_admin THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(array_agg(k), ARRAY[]::text[]) INTO v_keys
    FROM jsonb_object_keys(coalesce(_patch, '{}'::jsonb)) AS t(k);

  IF NOT v_admin THEN
    FOR v_class IN
      SELECT * FROM (VALUES
        ('service',    v_service_keys,    v_service_roles),
        ('pricing',    v_pricing_keys,    v_pricing_roles),
        ('routing',    v_routing_keys,    v_routing_roles),
        ('publishing', v_publishing_keys, v_settings_roles),
        ('addon',      v_addon_keys,      v_addon_roles)
      ) AS c(name, keys, roles)
    LOOP
      IF v_keys && v_class.keys AND NOT (v_role = ANY (v_class.roles)) THEN
        RAISE EXCEPTION 'not_authorized_for_policy_keys' USING ERRCODE = '42501', DETAIL = v_class.name;
      END IF;
    END LOOP;

    SELECT coalesce(array_agg(k), ARRAY[]::text[]) INTO v_touched
      FROM unnest(v_keys) AS t(k)
      WHERE NOT (k = ANY (v_service_keys || v_pricing_keys || v_routing_keys || v_publishing_keys || v_addon_keys || v_member_keys));
    IF array_length(v_touched, 1) > 0 AND NOT (v_role = ANY (v_settings_roles)) THEN
      RAISE EXCEPTION 'not_authorized_for_settings_keys' USING ERRCODE = '42501', DETAIL = array_to_string(v_touched, ',');
    END IF;
  END IF;

  -- A fee that differs from the saved one, on a dealership with priced
  -- vehicles, goes through the reviewed apply. Resending the saved value
  -- (a whole-settings save) is not a change and passes.
  IF _patch ?| ARRAY['doc_fee_enabled', 'doc_fee_amount'] THEN
    SELECT coalesce(settings, '{}'::jsonb) INTO v_current FROM public.dealer_profiles WHERE tenant_id = _tenant_id;
    v_current := coalesce(v_current, '{}'::jsonb);
    IF ((_patch ? 'doc_fee_enabled'
          AND public.doc_fee_setting_bool(_patch -> 'doc_fee_enabled') IS DISTINCT FROM public.doc_fee_setting_bool(v_current -> 'doc_fee_enabled'))
        OR (_patch ? 'doc_fee_amount'
          AND (CASE WHEN (_patch ->> 'doc_fee_amount') ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' THEN (_patch ->> 'doc_fee_amount')::numeric END)
              IS DISTINCT FROM
              (CASE WHEN (v_current ->> 'doc_fee_amount') ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*$' THEN (v_current ->> 'doc_fee_amount')::numeric END)))
       AND EXISTS (SELECT 1 FROM public.vehicle_listings
                   WHERE tenant_id = _tenant_id
                     AND (price IS NOT NULL OR advertised_price_before_doc IS NOT NULL)) THEN
      RAISE EXCEPTION 'doc_fee_change_requires_review'
        USING ERRCODE = '55000', DETAIL = 'Change the document fee through the reviewed fee change so every vehicle moves with it.';
    END IF;
  END IF;

  FOR v_class IN
    SELECT * FROM (VALUES
      ('service_policy_changed',    v_service_keys),
      ('pricing_policy_changed',    v_pricing_keys),
      ('routing_policy_changed',    v_routing_keys),
      ('publishing_policy_changed', v_publishing_keys),
      ('addon_policy_changed',      v_addon_keys)
    ) AS c(action, keys)
  LOOP
    SELECT array_agg(k) INTO v_touched
      FROM unnest(v_keys) AS t(k)
      WHERE k = ANY (v_class.keys);
    IF v_touched IS NOT NULL THEN
      INSERT INTO public.audit_log (action, entity_type, entity_id, store_id, user_id, details)
      VALUES (v_class.action, 'tenant', _tenant_id::text, _tenant_id::text, v_uid,
              jsonb_build_object('keys', to_jsonb(v_touched),
                'prev', (SELECT jsonb_object_agg(k, dp.settings -> k)
                         FROM unnest(v_touched) AS k, public.dealer_profiles dp
                         WHERE dp.tenant_id = _tenant_id),
                'next', (SELECT jsonb_object_agg(k, _patch -> k) FROM unnest(v_touched) AS k)));
    END IF;
  END LOOP;

  INSERT INTO public.dealer_profiles (tenant_id, settings, updated_by)
  VALUES (_tenant_id, coalesce(_patch, '{}'::jsonb), v_uid)
  ON CONFLICT (tenant_id) DO UPDATE
    SET settings   = coalesce(dealer_profiles.settings, '{}'::jsonb) || coalesce(_patch, '{}'::jsonb),
        updated_by = v_uid;

  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.merge_dealer_settings(uuid, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.merge_dealer_settings(uuid, jsonb) TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.doc_fee_basis(jsonb) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.doc_fee_row_plan(text, numeric, numeric, numeric, numeric, numeric) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.doc_fee_evidence_contradicts(text, numeric, numeric, numeric) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.doc_fee_basis(jsonb) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.doc_fee_row_plan(text, numeric, numeric, numeric, numeric, numeric) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.doc_fee_evidence_contradicts(text, numeric, numeric, numeric) TO authenticated, service_role;

